import numpy as np
names=['1','t','P','tP','P2','1/P','t2','tP2','P3','t/P','sqrtP','t2P']
B=[np.ones_like(t),t,P,t*P,P**2,1/P,t**2,t*P**2,P**3,t/P,np.sqrt(P),t**2*P]
A=np.column_stack(B)
def fit(cols):
    c,_,_,_=np.linalg.lstsq(A[:,cols],dP_dt,rcond=None)
    pred=A[:,cols]@c
    return c, 1-np.sum((dP_dt-pred)**2)/np.sum((dP_dt-dP_dt.mean())**2)
for cols in [[0,2,3,4],[0,2,3,4,1],[0,2,3,4,5],[2,3,4,5],[0,2,3,4,6],[0,1,2,3,4,5]]:
    c,r2=fit(cols); print([names[i] for i in cols],np.round(c,4),round(r2,6))
